def subsetsWithDup(nums):
    nums = sorted(nums)
    res, cur = [], []
    def bt(start):
        res.append(cur[:])
        for i in range(start, len(nums)):
            if i > start and nums[i] == nums[i - 1]:
                continue
            cur.append(nums[i])
            bt(i + 1)
            cur.pop()
    bt(0)
    return res

